import{_ as a,c as i,o as t,ae as n}from"./chunks/framework.DMK_uHmU.js";const g=JSON.parse('{"title":"How to Create a New Knowledge Base","description":"","frontmatter":{},"headers":[],"relativePath":"Administration/AI-Management/Knowledge-Bases/knowledge-base.md","filePath":"Administration/AI-Management/Knowledge-Bases/knowledge-base.md"}'),o={name:"Administration/AI-Management/Knowledge-Bases/knowledge-base.md"};function l(s,e,r,d,c,h){return t(),i("div",null,e[0]||(e[0]=[n('<h1 id="how-to-create-a-new-knowledge-base" tabindex="-1">How to Create a New Knowledge Base <a class="header-anchor" href="#how-to-create-a-new-knowledge-base" aria-label="Permalink to &quot;How to Create a New Knowledge Base&quot;">​</a></h1><h2 id="introduction" tabindex="-1">Introduction <a class="header-anchor" href="#introduction" aria-label="Permalink to &quot;Introduction&quot;">​</a></h2><p>Learn how to create and configure a new Knowledge Base (KB) in the Sairis platform. Knowledge Bases are essential for organizing and managing information that can be used by the AI Assistant.</p><h2 id="why-this-matters" tabindex="-1">Why This Matters <a class="header-anchor" href="#why-this-matters" aria-label="Permalink to &quot;Why This Matters&quot;">​</a></h2><p>Knowledge Bases allow you to create structured, searchable repositories of information. By carefully curating and organizing your Knowledge Base, you can improve the accuracy and relevance of AI-generated responses across your organization.</p><h2 id="prerequisites" tabindex="-1">Prerequisites <a class="header-anchor" href="#prerequisites" aria-label="Permalink to &quot;Prerequisites&quot;">​</a></h2><p>Before creating a Knowledge Base, ensure you have:</p><ul><li>Access to the Knowledge Base management section</li><li>Necessary permissions to create and configure Knowledge Bases</li></ul><h2 id="step-by-step-instructions" tabindex="-1">Step-by-Step Instructions <a class="header-anchor" href="#step-by-step-instructions" aria-label="Permalink to &quot;Step-by-Step Instructions&quot;">​</a></h2><h3 id="accessing-knowledge-base-creation" tabindex="-1">Accessing Knowledge Base Creation <a class="header-anchor" href="#accessing-knowledge-base-creation" aria-label="Permalink to &quot;Accessing Knowledge Base Creation&quot;">​</a></h3><ol><li>Navigate to the Knowledge Bases section in the AI Management menu</li><li>Click the <strong>Add KB</strong> button</li></ol><h3 id="configure-basic-information" tabindex="-1">Configure Basic Information <a class="header-anchor" href="#configure-basic-information" aria-label="Permalink to &quot;Configure Basic Information&quot;">​</a></h3><ol><li><p><strong>Name</strong>: Enter a clear, descriptive name for your Knowledge Base</p><ul><li>Example: &quot;Auto Maintenance&quot;</li><li>Maximum length: 255 characters</li></ul></li><li><p><strong>Initials</strong>: Provide 1-2 character initials to represent the Knowledge Base</p><ul><li>Example: &quot;AU&quot;</li><li>Used for quick identification</li></ul></li><li><p><strong>Description</strong>: Write a detailed description explaining the purpose of the Knowledge Base</p><ul><li>Be specific about the type of information contained</li><li>Maximum length: Approximately 500 characters</li></ul></li></ol><h3 id="advanced-configuration" tabindex="-1">Advanced Configuration <a class="header-anchor" href="#advanced-configuration" aria-label="Permalink to &quot;Advanced Configuration&quot;">​</a></h3><h4 id="ai-model-settings" tabindex="-1">AI Model Settings <a class="header-anchor" href="#ai-model-settings" aria-label="Permalink to &quot;AI Model Settings&quot;">​</a></h4><ol><li><p>Select an <strong>AI Foundation Model</strong></p><ul><li>Options: <ul><li>haiku</li><li>sonnet (default)</li></ul></li></ul></li><li><p>Choose <strong>Creativity Level</strong></p><ul><li>Options: <ul><li>Creative</li><li>Balanced</li><li>Precise</li></ul></li></ul></li><li><p><strong>Optional</strong>: Add custom <strong>Instructions</strong> for the AI&#39;s behavior with this Knowledge Base</p></li></ol><h4 id="search-and-access-configuration" tabindex="-1">Search and Access Configuration <a class="header-anchor" href="#search-and-access-configuration" aria-label="Permalink to &quot;Search and Access Configuration&quot;">​</a></h4><ol><li><p><strong>KB Search Results</strong></p><ul><li>Set the number of results returned when searching the Knowledge Base</li><li>Default: 10 results</li><li>Range: 1-100 results</li></ul></li><li><p><strong>Results Match Score</strong></p><ul><li>Minimum score for search results</li><li>Recommended: 58-60</li><li>Range: 1-100</li></ul></li></ol><h4 id="visibility-and-sharing" tabindex="-1">Visibility and Sharing <a class="header-anchor" href="#visibility-and-sharing" aria-label="Permalink to &quot;Visibility and Sharing&quot;">​</a></h4><ol><li><p><strong>Allow Copies</strong></p><ul><li>Toggle to permit others to create derivative work from this Knowledge Base</li></ul></li><li><p><strong>Publish in Quick List</strong></p><ul><li>Show this Knowledge Base in the main AI Selector dropdown</li></ul></li><li><p><strong>Publish on Home Page</strong></p><ul><li>Display the Knowledge Base on users&#39; home pages</li></ul></li></ol><h3 id="final-steps" tabindex="-1">Final Steps <a class="header-anchor" href="#final-steps" aria-label="Permalink to &quot;Final Steps&quot;">​</a></h3><ol><li>Review all settings</li><li>Click <strong>Submit</strong> to create the Knowledge Base</li></ol><h2 id="user-privileges-needed" tabindex="-1">User Privileges Needed <a class="header-anchor" href="#user-privileges-needed" aria-label="Permalink to &quot;User Privileges Needed&quot;">​</a></h2><table tabindex="0"><thead><tr><th><strong>Action</strong></th><th><strong>Privilege Needed</strong></th></tr></thead><tbody><tr><td>To create a Knowledge Base</td><td>Platform Access Level: Admin</td></tr><tr><td>To modify Knowledge Base settings</td><td>Administrator Access Level: Full Knowledge Base Management</td></tr></tbody></table><h2 id="best-practices" tabindex="-1">Best Practices <a class="header-anchor" href="#best-practices" aria-label="Permalink to &quot;Best Practices&quot;">​</a></h2><ul><li>Choose a clear, descriptive name</li><li>Write a comprehensive description</li><li>Set an appropriate creativity level</li><li>Configure search parameters carefully</li><li>Regularly update and maintain your Knowledge Base</li></ul><div class="language-Final vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">Final</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span></span></span></code></pre></div>',27)]))}const p=a(o,[["render",l]]);export{g as __pageData,p as default};
